package com.bank.sortedprint;

import java.util.*;
import java.util.logging.*;

public class SortedPrintDemo {
    private static final Logger log = Logger.getLogger("SortedPrint");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> data = Arrays.asList(5, 3, 8, 1, 9, 2, 7, 4, 6);
        SortedPrintService service = new SortedPrintService();

        log.info("parallel sorted + forEach → order NOT guaranteed:");
        service.parallelForEach(data);
        log.info("parallel sorted + forEachOrdered → order preserved:");
        service.parallelForEachOrdered(data);
    }
}

// ─── Would be in service/SortedPrintService.java ───
class SortedPrintService {
    // sorted sets encounter order, but parallel forEach consumes UNORDERED
    void parallelForEach(List<Integer> data) {
        data.parallelStream().sorted().forEach(n -> System.out.print(n + " ")); // jumbled
        System.out.println();
    }

    // forEachOrdered preserves the sorted encounter order
    void parallelForEachOrdered(List<Integer> data) {
        data.parallelStream().sorted().forEachOrdered(n -> System.out.print(n + " ")); // 1..9
        System.out.println();
    }
}
